'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const KEY='cima-el-roble-v1', DRAFT=KEY+'-draft';
let defaults, content, saved, activeTab='appearance', dirty=false, toastTimer;
const clone=x=>JSON.parse(JSON.stringify(x));
const get=(path,obj=content)=>path.split('.').reduce((o,k)=>o?.[k],obj);
function set(path,value){const parts=path.split('.'),last=parts.pop();parts.reduce((o,k)=>o[k],content)[last]=value;dirty=true;render();try{localStorage.setItem(DRAFT,JSON.stringify(content))}catch{toast('El navegador no tiene espacio. Exporta tus contenidos.')}$('#saveState').textContent='Borrador con cambios · vista previa';}
const themes={olivo:{name:'Olivo & arena',colors:['#f5f3ed','#2d352b','#536048','#e9e7de','#6d7268','#d8d9ce']},costa:{name:'Brisa costera',colors:['#f1f5f3','#233d42','#34666c','#e2ece9','#596e70','#ceddda']},arcilla:{name:'Arcilla cálida',colors:['#f7f1e9','#49372e','#966344','#efe1d3','#806b60','#e1d3c5']},noche:{name:'Piedra & noche',colors:['#eeede9','#242b30','#46525d','#e0e1dd','#626d74','#cdd0cd']}};
const fonts={manrope:'Manrope,Arial,sans-serif',system:'system-ui,-apple-system,BlinkMacSystemFont,sans-serif',arial:'Arial,Helvetica,sans-serif',humanist:'"Trebuchet MS",Verdana,sans-serif'};
const names={appearance:'Apariencia',brand:'Identidad',nav:'Menú',hero:'Portada',about:'El hostal',rooms:'Habitaciones',pause:'Franja',gallery:'Galería',location:'Ubicación',booking:'Consulta',faq:'Preguntas',contact:'Contacto',footer:'Pie de página'};
const labels={name:'Nombre',subtitle:'Bajada de marca',about:'El hostal',rooms:'Habitaciones',gallery:'Galería',location:'Ubicación',eyebrow:'Texto superior',title:'Título',body:'Descripción',cta:'Texto del botón',caption:'Pie de imagen',side:'Texto lateral',signature:'Firma',feature1:'Característica 1',feature2:'Característica 2',feature3:'Característica 3',note:'Nota informativa',align:'Alineación de textos',image:'Fotografía',image1:'Primera fotografía',image2:'Segunda fotografía',caption1:'Pie de primera imagen',caption2:'Pie de segunda imagen',first:'Primera frase',second:'Segunda frase',third:'Tercera frase',address:'Dirección',ocean:'Nombre del océano',town:'Localidad',mapnote:'Nota de ilustración',arrival:'Etiqueta llegada',departure:'Etiqueta salida',guests:'Etiqueta huéspedes',oneGuest:'Opción 1 huésped',twoGuests:'Opción 2 huéspedes',q1:'Pregunta 1',a1:'Respuesta 1',q2:'Pregunta 2',a2:'Respuesta 2',q3:'Pregunta 3',a3:'Respuesta 3',phone:'Número WhatsApp con código de país',phoneDisplay:'Teléfono visible',blog:'Enlace al blog',credit:'Crédito'};
function validImage(src){return typeof src==='string'&&(src.startsWith('assets/')||/^https:\/\//i.test(src)||/^data:image\/(webp|png|jpeg);base64,/i.test(src));}
function validate(input){if(!input||input.version!==1)throw Error('Formato incompatible.');const next=clone(defaults);function walk(base,other){for(const k of Object.keys(base)){if(!(k in (other||{})))continue;if(typeof base[k]==='object'){walk(base[k],other[k]);}else if(typeof base[k]==='string'&&typeof other[k]==='string'){if(other[k].length>(k==='src'?650000:2000))throw Error('Contenido demasiado grande.');base[k]=other[k];}}}walk(next,input);if(!themes[next.appearance.palette]||!fonts[next.appearance.font]||!['balanced','airy','compact'].includes(next.appearance.layout))throw Error('Apariencia no válida.');if(!/^\d{8,15}$/.test(next.contact.phone))throw Error('El teléfono debe tener entre 8 y 15 dígitos, sin espacios.');for(const group of Object.values(next)){if(typeof group!=='object')continue;for(const [k,v]of Object.entries(group)){if(k==='align'&&!['left','center','right'].includes(v))throw Error('Alineación no válida.');if(v&&typeof v==='object'&&'src'in v){if(!validImage(v.src)||!['small','medium','large'].includes(v.size)||!['center','top','bottom'].includes(v.position))throw Error('Configuración de imagen no válida.');}}}return next;}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function render(){for(const el of $$('[data-text]'))el.textContent=get(el.dataset.text)??'';for(const im of $$('[data-image]')){const data=get(im.dataset.image);if(im.getAttribute('src')!==data.src)im.src=data.src;im.alt=data.alt;im.dataset.size=data.size;im.style.objectPosition=data.position;}
 for(const el of $$('[data-section]'))el.dataset.align=get(el.dataset.section+'.align')||'left';
 const colors=themes[content.appearance.palette].colors;['paper','ink','accent','soft','muted','line'].forEach((n,i)=>document.documentElement.style.setProperty('--'+n,colors[i]));document.documentElement.style.setProperty('--site-font',fonts[content.appearance.font]);document.body.classList.remove('layout-balanced','layout-airy','layout-compact');document.body.classList.add('layout-'+content.appearance.layout);$('#phoneLink').href='tel:+'+content.contact.phone;$('#mapLink').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(content.location.address);$('#guests').options[0].textContent=content.booking.oneGuest;$('#guests').options[1].textContent=content.booking.twoGuests;document.title=content.brand.name+' — Algarrobo';}
function field(label,path,type='text',options){const wrap=document.createElement('label');wrap.className='editor-field';const span=document.createElement('span');span.textContent=label;wrap.append(span);let input;if(type==='select'){input=document.createElement('select');for(const [value,text]of options){const o=document.createElement('option');o.value=value;o.textContent=text;input.append(o);}}else if(type==='textarea'){input=document.createElement('textarea');input.maxLength=2000;}else{input=document.createElement('input');input.type='text';input.maxLength=type==='url'?1500:2000;}input.value=get(path);input.addEventListener(type==='select'?'change':'input',()=>{if(type==='url'&&!validImage(input.value)){input.setCustomValidity('Utilise una URL HTTPS de una imagen.');input.reportValidity();return;}if(path==='contact.phone'&&!/^\d{8,15}$/.test(input.value)){input.setCustomValidity('Solo dígitos, incluyendo el código de país.');return;}input.setCustomValidity('');set(path,input.value);});wrap.append(input);return wrap;}
function imageField(label,path){const block=document.createElement('div');block.className='editor-field';const title=document.createElement('span');title.textContent=label;block.append(title);const preview=document.createElement('img');preview.src=get(path+'.src');preview.alt='Vista previa de '+label;block.append(preview);const upload=document.createElement('input');upload.type='file';upload.accept='image/jpeg,image/png,image/webp';upload.setAttribute('aria-label','Reemplazar '+label);upload.addEventListener('change',async()=>{const file=upload.files[0];if(!file)return;if(file.size>12000000){toast('Usa una imagen de menos de 12 MB.');return;}try{const bitmap=await createImageBitmap(file);const factor=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*factor));canvas.height=Math.max(1,Math.round(bitmap.height*factor));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/webp',.8);bitmap.close();if(data.length>650000){toast('La imagen es demasiado pesada. Usa una más pequeña.');return;}set(path+'.src',data);preview.src=data;toast('Imagen lista en la vista previa.');}catch{toast('No se pudo leer esa imagen. Prueba con JPG, PNG o WebP.');}});block.append(upload);const url=field('O usa una URL HTTPS',path+'.src','url');const urlInput=url.querySelector('input');if(get(path+'.src').startsWith('data:')){urlInput.value='';urlInput.placeholder='Imagen cargada desde tu dispositivo';}block.append(url);block.append(field('Descripción de la imagen',path+'.alt'));const opts=document.createElement('div');opts.className='image-options';opts.append(field('Tamaño',path+'.size','select',[['small','Pequeña'],['medium','Mediana'],['large','Grande']]));opts.append(field('Encuadre',path+'.position','select',[['top','Arriba'],['center','Centro'],['bottom','Abajo']]));block.append(opts);return block;}
function drawEditor(){const tabs=$('#editorTabs');tabs.replaceChildren();for(const [key,label]of Object.entries(names)){const b=document.createElement('button');b.textContent=label;b.role='tab';b.id='tab-'+key;b.setAttribute('aria-controls','editorFields');b.setAttribute('aria-selected',String(key===activeTab));b.tabIndex=key===activeTab?0:-1;b.onclick=()=>{activeTab=key;drawEditor();$('#tab-'+key).focus();};b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=Object.keys(names);let i=keys.indexOf(activeTab);i=e.key==='Home'?0:e.key==='End'?keys.length-1:(i+(e.key==='ArrowRight'?1:-1)+keys.length)%keys.length;activeTab=keys[i];drawEditor();$('#tab-'+activeTab).focus();};tabs.append(b);}const area=$('#editorFields');area.setAttribute('aria-labelledby','tab-'+activeTab);area.replaceChildren();if(activeTab==='appearance'){const h=document.createElement('h3');h.className='editor-group';h.textContent='Combinaciones de color';area.append(h);const grid=document.createElement('div');grid.className='theme-grid';for(const [key,t]of Object.entries(themes)){const b=document.createElement('button');b.className='theme-card'+(content.appearance.palette===key?' active':'');b.setAttribute('aria-pressed',String(content.appearance.palette===key));const sw=document.createElement('span');sw.className='theme-swatches';t.colors.slice(0,3).forEach(c=>{const i=document.createElement('i');i.style.background=c;sw.append(i);});b.append(sw,document.createTextNode(t.name));b.onclick=()=>{set('appearance.palette',key);drawEditor();};grid.append(b);}area.append(grid);area.append(field('Tipografía','appearance.font','select',[['manrope','Manrope · ligera'],['system','Sistema · moderna'],['arial','Arial · neutra'],['humanist','Trebuchet · cercana']]));area.append(field('Distribución y espacios','appearance.layout','select',[['balanced','Equilibrada'],['airy','Más aire'],['compact','Compacta']]));const help=document.createElement('p');help.className='editor-help';help.textContent='Cada combinación mantiene la armonía del sitio completo. En cada sección puedes editar textos, alinear el contenido y reemplazar sus imágenes.';area.append(help);}else{const h=document.createElement('h3');h.className='editor-group';h.textContent=names[activeTab];area.append(h);for(const [key,value]of Object.entries(content[activeTab])){const path=activeTab+'.'+key;if(typeof value==='object'){area.append(imageField(labels[key]||key,path));}else if(key==='align'){area.append(field(labels[key],path,'select',[['left','Izquierda'],['center','Centro'],['right','Derecha']]));}else{const multiline=['title','body','note','address'].includes(key)||key.startsWith('a');area.append(field(labels[key]||key,path,multiline?'textarea':'text'));}}}tabs.querySelector('[aria-selected=true]')?.scrollIntoView({block:'nearest',inline:'nearest'});}
function openEditor(){drawEditor();$('#editor').hidden=false;$('#editorBackdrop').hidden=false;document.body.classList.add('editing');$('#closeEditor').focus();}function closeEditor(){$('#editor').hidden=true;$('#editorBackdrop').hidden=true;document.body.classList.remove('editing');$('#openEditor').focus();}
function localDate(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function nextDate(s){const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+1);return localDate(d);}
function setupDates(){const now=localDate(new Date());$('#arrival').min=now;$('#arrival').value=now;$('#departure').value=nextDate(now);$('#departure').min=nextDate(now);$('#arrival').addEventListener('change',()=>{const value=$('#arrival').value;if(!value)return;const min=nextDate(value);$('#departure').min=min;if($('#departure').value<min)$('#departure').value=min;});}
async function init(){try{const r=await fetch('content.json');if(!r.ok)throw Error('Contenido no disponible');defaults=await r.json();content=clone(defaults);saved=clone(defaults);try{const raw=localStorage.getItem(KEY);if(raw)saved=validate(JSON.parse(raw));content=clone(saved);const draft=localStorage.getItem(DRAFT);if(draft){content=validate(JSON.parse(draft));dirty=JSON.stringify(content)!==JSON.stringify(saved);if(dirty)$('#saveState').textContent='Borrador recuperado · vista previa';}}catch{content=clone(defaults);saved=clone(defaults);}render();setupDates();}catch{toast('No se pudo cargar el contenido. Recarga la página.');return;}
 $('#menuToggle').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menuToggle').setAttribute('aria-expanded',String(open));$('#menuToggle').setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');};for(const a of $$('#nav a'))a.onclick=()=>{$('#nav').classList.remove('open');$('#menuToggle').setAttribute('aria-expanded','false');$('#menuToggle').setAttribute('aria-label','Abrir menú');};
 $('#bookingForm').onsubmit=e=>{e.preventDefault();const a=$('#arrival').value,d=$('#departure').value;const today=localDate(new Date());if(a<today||!d||d<=a){toast('La salida debe ser posterior a la llegada.');return;}const fmt=s=>new Intl.DateTimeFormat('es-CL',{day:'numeric',month:'long',year:'numeric'}).format(new Date(s+'T12:00:00'));const text='Hola, quisiera consultar disponibilidad en '+content.brand.name+' para '+$('#guests').value+' persona(s), del '+fmt(a)+' al '+fmt(d)+'. ¿Me podrían indicar la tarifa y condiciones?';window.open('https://wa.me/'+content.contact.phone+'?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');};
 for(const b of $$('[data-lightbox]'))b.onclick=()=>{const data=get(b.dataset.lightbox);$('#lightboxImage').src=data.src;$('#lightboxImage').alt=data.alt;$('#lightboxCaption').textContent=data.alt;$('#lightbox').showModal();};$('.close-lightbox').onclick=()=>$('#lightbox').close();$('#lightbox').onclick=e=>{if(e.target===$('#lightbox'))$('#lightbox').close();};
 $('#openEditor').onclick=openEditor;$('#closeEditor').onclick=closeEditor;$('#editorBackdrop').onclick=closeEditor;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#editor').hidden)closeEditor();if(e.key==='Tab'&&!$('#editor').hidden){const focus=$$('#editor button,#editor input:not([hidden]),#editor select,#editor textarea').filter(x=>x.tabIndex>=0&&x.offsetParent!==null);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
 $('#saveLocal').onclick=()=>{try{content=validate(content);localStorage.setItem(KEY,JSON.stringify(content));localStorage.removeItem(DRAFT);saved=clone(content);dirty=false;$('#saveState').textContent='Versión guardada en este navegador';toast('Versión local guardada. No cambia el sitio oficial.');}catch(e){toast(e.message||'No se pudo guardar. Exporta el contenido.');}};
 $('#discardDraft').onclick=()=>{content=clone(saved);dirty=false;try{localStorage.removeItem(DRAFT)}catch{}render();drawEditor();$('#saveState').textContent='Borrador descartado';toast('Volviste a tu última versión local.');};
 $('#resetContent').onclick=()=>{if(!confirm('¿Restablecer el diseño y los contenidos iniciales en este navegador?'))return;content=clone(defaults);saved=clone(defaults);try{localStorage.removeItem(KEY);localStorage.removeItem(DRAFT)}catch{}dirty=false;render();drawEditor();$('#saveState').textContent='Diseño inicial restablecido';};
 $('#exportContent').onclick=()=>{const blob=new Blob([JSON.stringify(content,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='el-roble-contenidos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Contenidos exportados.');};
 $('#importContent').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4000000)throw Error('El archivo debe pesar menos de 4 MB.');content=validate(JSON.parse(await file.text()));dirty=true;render();drawEditor();try{localStorage.setItem(DRAFT,JSON.stringify(content))}catch{}$('#saveState').textContent='Contenidos importados · sin guardar';toast('Archivo importado. Revisa y guarda la versión local.');}catch(err){toast(err.message||'El archivo no es válido.');}e.target.value='';};
 if(new URLSearchParams(location.search).get('editar')==='1')openEditor();
}
init();
